css:
:root{--bg:#0b0a09;--surf:#12100e;--gold:#c9a24d;--copper:#b87333;--text:#ece5d6;--mute:#a09580;--hair:rgba(201,162,77,.28);
box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:84px}
body{margin:0;background:var(--bg);color:var(--text);font-family:'Jost',system-ui,sans-serif;line-height:1.8;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
h1,    h2,    h3,    .serif{font-family:'Cormorant Garamond',Georgia,serif;font-weight:500}
.eyebrow{font-size:.72rem;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);font-weight:500}
.btn{display:inline-block;padding:15px 36px;font-size:.74rem;letter-spacing:.24em;text-transform:uppercase;font-weight:500;border:1px solid var(--gold);color:var(--gold);transition:.25s}
.btn:hover{background:var(--gold);color:#0b0a09}
.btn.solid{background:var(--gold);color:#0b0a09}
.btn.solid:hover{background:transparent;color:var(--gold)}
.cta{display:flex;gap:18px;flex-wrap:wrap;margin-top:34px}
/* hero */
.hero{position:relative;overflow:hidden;text-align:center;padding:64px 6vw 68px;background:radial-gradient(ellipse 75% 65% at 50% 25%,#2b1e0c,var(--bg) 75%)}
.clock{position:absolute;z-index:0;height:auto;pointer-events:none;color:var(--gold);opacity:.13}
.clock.a{width:760px;left:-200px;top:-180px;transform:rotate(-14deg)}
.clock.b{width:620px;right:-160px;bottom:-240px;transform:rotate(18deg);opacity:.09}
.hero:after{content:"";position:absolute;inset:20px 3vw;border:1px solid var(--hair);pointer-events:none}
.hero>*:not(.clock){position:relative;z-index:1}
.hero .logo{width:min(380px,70vw);margin:0 auto 30px;display:block;filter:drop-shadow(0 10px 40px rgba(201,162,77,.2))}
.hero h1{font-size:clamp(2.6rem,6.6vw,5.2rem);line-height:1.05;font-weight:400;margin:16px auto 0;max-width:900px}
.hero h1 em{color:var(--gold)}
.hero .cta{justify-content:center}
.orn{display:flex;align-items:center;justify-content:center;gap:16px;color:var(--gold)}
.orn:before,    .orn:after{content:"";height:1px;width:90px;background:linear-gradient(90deg,transparent,var(--gold))}
.orn:after{transform:scaleX(-1)}
.orn svg{width:13px;height:13px}
section{padding:110px 6vw;max-width:1200px;margin:auto}
.wide{max-width:none;background:var(--surf);border-block:1px solid var(--hair)}
.wide>.in{max-width:1200px;margin:auto}
h2{font-size:clamp(2.1rem,4.4vw,3.3rem);margin:14px 0 20px;font-weight:400;line-height:1.1}
h2 em{color:var(--gold)}
p{color:var(--mute);margin:0 0 18px}
.split{display:grid;grid-template-columns:1.1fr 1fr;gap:80px;align-items:center}
.frame{position:relative;aspect-ratio:4/5;max-width:440px;margin-left:auto;border:1px solid var(--hair);display:flex;align-items:center;justify-content:center;background:linear-gradient(160deg,#1c150b,#0e0c0a)}
.frame:before{content:"";position:absolute;inset:-14px 14px 14px -14px;border:1px solid var(--hair);z-index:-1}
.frame img{width:72%;opacity:.95}
.frame small{position:absolute;bottom:18px;font-size:.62rem;letter-spacing:.3em;text-transform:uppercase;color:var(--mute)}
.head{text-align:center;margin-bottom:60px}
.head p{max-width:560px;margin:0 auto}
.auc{border:1px solid var(--hair);display:grid;grid-template-columns:1fr auto;gap:40px;align-items:center;padding:48px 52px;position:relative}
.auc:before{content:"";position:absolute;inset:8px;border:1px solid rgba(201,162,77,.13);pointer-events:none}
.auc h3{font-size:1.9rem;margin:0 0 8px}
.auc p{margin:0}
.auc-btns{display:flex;flex-direction:column;gap:14px;width:100%;max-width:320px;min-width:0}
.auc-btns .btn{text-align:center}
.cats{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));border-top:1px solid var(--hair);border-left:1px solid var(--hair)}
.cat{padding:36px 32px;border-right:1px solid var(--hair);border-bottom:1px solid var(--hair);transition:.3s}
.cat:hover{background:rgba(201,162,77,.06)}
.cat h3{font-size:1.45rem;margin:0 0 6px}
.cat p{margin:0;font-size:.88rem;line-height:1.6}
blockquote{margin:0 auto;max-width:760px;text-align:center}
blockquote:before{content:"“";display:block;font-family:'Cormorant Garamond',serif;font-size:6rem;line-height:.6;color:var(--copper)}
blockquote p{font-family:'Cormorant Garamond',serif;font-style:italic;font-size:clamp(1.4rem,2.6vw,2rem);line-height:1.5;color:var(--text)}
blockquote cite{font-style:normal;font-size:.74rem;letter-spacing:.3em;text-transform:uppercase;color:var(--gold)}
.team{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:30px;max-width:760px;margin:auto}
.person{border:1px solid var(--hair);text-align:center;padding:44px 24px}
.mono{width:104px;height:104px;border-radius:50%;border:1px solid var(--gold);margin:0 auto 22px;display:flex;align-items:center;justify-content:center;font-family:'Cormorant Garamond',serif;font-size:2.2rem;color:var(--gold);box-shadow:0 0 0 6px var(--bg),0 0 0 7px var(--hair)}
.person h3{font-size:1.6rem;margin:0}
.person .eyebrow{color:var(--mute)}
.why{text-align:center;background:linear-gradient(rgba(11,10,9,.82),rgba(11,10,9,.9)),radial-gradient(ellipse at 50% 0,#3a2810,var(--bg));border-block:1px solid var(--hair);max-width:none}
.why h2{max-width:860px;margin:14px auto 0}
.why .cta{justify-content:center}
footer{padding:70px 6vw 36px;background:#070606}
.fg{max-width:1200px;margin:auto;display:grid;grid-template-columns:1.3fr 1fr 1fr 1.3fr;gap:40px}
.fg img{width:190px}
.fg h4{margin:0 0 14px;font-size:.72rem;letter-spacing:.28em;text-transform:uppercase;color:var(--gold);font-weight:500}
.fg a,    .fg div div{display:block;color:var(--mute);font-size:.9rem;line-height:2}
.fg a:hover{color:var(--gold)}
.fine{max-width:1200px;margin:50px auto 0;padding-top:24px;border-top:1px solid var(--hair);color:var(--mute);font-size:.76rem;letter-spacing:.05em;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}

.car{max-width:900px;margin:auto;text-align:center}
.strike{position:relative;width:64px;height:64px;margin:0 auto 6px}
.gav{width:64px;height:64px;transform-origin:40% 40%;position:relative;z-index:1}
.ring{position:absolute;left:50%;bottom:6px;width:20px;height:20px;margin-left:-10px;border:1px solid var(--gold);border-radius:50%;opacity:0}
.row{display:grid;grid-template-columns:48px 1fr 48px;gap:20px;align-items:center;min-height:300px}
.arr{width:46px;height:46px;border:1px solid var(--hair);background:none;color:var(--gold);font-size:1.6rem;line-height:1;cursor:pointer;transition:.25s;font-family:'Cormorant Garamond',serif}
.arr:hover{background:var(--gold);color:#0b0a09}
.q:before{content:"“";display:block;font-family:'Cormorant Garamond',serif;font-size:5rem;line-height:.5;color:var(--copper);margin-bottom:10px}
.q{margin:0;will-change:transform,opacity,filter}
.dots{display:flex;gap:16px;justify-content:center;margin-top:34px}
.dots button{width:11px;height:11px;transform:rotate(45deg);border:1px solid var(--gold);background:none;padding:0;cursor:pointer;transition:.3s}
.dots button.on{background:var(--gold);transform:rotate(45deg) scale(1.35)}
.bar{height:1px;background:var(--hair);max-width:220px;margin:22px auto 0;overflow:hidden}
.bar i{display:block;height:100%;width:100%;background:var(--gold);transform:scaleX(0);transform-origin:left}
@media(max-width:640px){.row{grid-template-columns:1fr;min-height:360px}.arr{display:none}}
@media(max-width:860px){.split{grid-template-columns:1fr;gap:50px}.frame{margin:0 auto}.auc{grid-template-columns:1fr;padding:36px 28px}.auc-btns{max-width:none}.fg{grid-template-columns:1fr 1fr}section{padding:80px 6vw}}

.wide>.in{padding:110px 6vw}.team-note{text-align:center;margin-top:46px}.fine a{color:var(--gold)}
